/**
 * useProducts Hook Tests
 *
 * Tests for the custom useProducts hook that manages product CRUD operations.
 * This file tests fetching products, creating products, updating products,
 * deleting products, and toggling product visibility.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook, waitFor, act } from '@testing-library/react'
import { useProducts } from '@/hooks/useProducts'
import {
  createMockProduct,
  createMockCategory,
  createMockCurrentPrice,
} from '@/__tests__/fixtures/test-data'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'

describe('useProducts Hook', () => {
  const mockOrganizationId = 'test-org-id'

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('Initial State', () => {
    it('should initialize with empty products array', () => {
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const { result } = renderHook(() => useProducts(mockOrganizationId))

      expect(result.current.products).toEqual([])
      expect(result.current.isLoading).toBe(false)
      expect(result.current.error).toBeNull()
    })

    it('should provide all CRUD methods', () => {
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const { result } = renderHook(() => useProducts(mockOrganizationId))

      expect(typeof result.current.fetchProducts).toBe('function')
      expect(typeof result.current.createProduct).toBe('function')
      expect(typeof result.current.updateProduct).toBe('function')
      expect(typeof result.current.deleteProduct).toBe('function')
      expect(typeof result.current.toggleVisibility).toBe('function')
    })
  })

  describe('fetchProducts', () => {
    it('should fetch products with prices and categories', async () => {
      // Arrange
      const mockProducts = [
        createMockProduct({
          id: 'prod-1',
          name: 'Test Product 1',
          category_id: 'cat-1',
          organization_id: mockOrganizationId,
        }),
        createMockProduct({
          id: 'prod-2',
          name: 'Test Product 2',
          category_id: 'cat-1',
          organization_id: mockOrganizationId,
        }),
      ]

      const mockPrices = [
        createMockCurrentPrice({ product_id: 'prod-1', price: 45.5 }),
        createMockCurrentPrice({ product_id: 'prod-2', price: 32.0 }),
      ]

      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Main Dishes',
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductsQueryBuilder(mockProducts)
        }
        if (table === 'current_prices') {
          return createPricesQueryBuilder(mockPrices)
        }
        if (table === 'categories') {
          return createCategoriesQueryBuilder(mockCategories)
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductsQueryBuilder(data: any[]) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createPricesQueryBuilder(data: any[]) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          in: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createCategoriesQueryBuilder(data: any[]) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.fetchProducts()
      })

      // Assert
      await waitFor(() => {
        expect(result.current.products).toHaveLength(2)
      })

      expect(result.current.products[0].name).toBe('Test Product 1')
      expect(result.current.products[0].current_price?.price).toBe(45.5)
      expect(result.current.products[0].category?.name).toBe('Main Dishes')
      expect(result.current.isLoading).toBe(false)
      expect(result.current.error).toBeNull()
    })

    it('should handle fetch error gracefully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createErrorQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createErrorQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.fetchProducts()
      })

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe('Failed to fetch products')
      })

      expect(result.current.products).toEqual([])
      expect(result.current.isLoading).toBe(false)
    })

    it('should not fetch when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn()
      mockClient.from = fromMock as any

      // Act
      const { result } = renderHook(() => useProducts(undefined))

      await act(async () => {
        await result.current.fetchProducts()
      })

      // Assert
      expect(fromMock).not.toHaveBeenCalled()
      expect(result.current.products).toEqual([])
    })

    it('should set loading state during fetch', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let resolvePromise: (value: any) => void
      const delayedPromise = new Promise((resolve) => {
        resolvePromise = resolve
      })

      const fromMock = vi.fn(() => {
        return createDelayedQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createDelayedQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          in: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return delayedPromise.then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      let fetchPromise: Promise<void>
      act(() => {
        fetchPromise = result.current.fetchProducts()
      })

      // Assert - loading should be true
      await waitFor(() => {
        expect(result.current.isLoading).toBe(true)
      })

      // Resolve the promise
      act(() => {
        resolvePromise!({ data: [], error: null })
      })

      await act(async () => {
        await fetchPromise!
      })

      // Assert - loading should be false
      await waitFor(() => {
        expect(result.current.isLoading).toBe(false)
      })
    })
  })

  describe('createProduct', () => {
    it('should create a new product successfully', async () => {
      // Arrange
      const newProductId = 'new-prod-123'

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductInsertQueryBuilder()
        }
        if (table === 'price_ledger') {
          return createPriceInsertQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => queryBuilder),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: newProductId, name: 'New Product' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createPriceInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => {
            return Promise.resolve({
              data: null,
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      let productId: string = ''
      await act(async () => {
        productId = await result.current.createProduct({
          name: 'New Product',
          description: 'Test description',
          price: 99.99,
        })
      })

      // Assert
      expect(productId).toBe(newProductId)
    })

    it('should create product with trimmed name', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedData: any = null

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductInsertQueryBuilder()
        }
        if (table === 'price_ledger') {
          return createPriceInsertQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn((data) => {
            capturedData = data
            return queryBuilder
          }),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: 'new-prod-123' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createPriceInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => {
            return Promise.resolve({
              data: null,
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.createProduct({
          name: '  Test Product  ',
        })
      })

      // Assert
      expect(capturedData.name).toBe('Test Product')
    })

    it('should create product with price ledger entry', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let priceLedgerInsertCalled = false
      let capturedPriceData: any = null

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductInsertQueryBuilder()
        }
        if (table === 'price_ledger') {
          return createPriceInsertQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => queryBuilder),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: 'new-prod-123' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createPriceInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn((data) => {
            priceLedgerInsertCalled = true
            capturedPriceData = data
            return Promise.resolve({
              data: null,
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.createProduct({
          name: 'Test Product',
          price: 49.99,
        })
      })

      // Assert
      expect(priceLedgerInsertCalled).toBe(true)
      expect(capturedPriceData.price).toBe(49.99)
      expect(capturedPriceData.currency).toBe('TRY')
      expect(capturedPriceData.change_reason).toBe('Initial price')
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useProducts(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.createProduct({
            name: 'Test Product',
          })
        })
      }).rejects.toThrow('Organization ID is required')
    })

    it('should handle database error during creation', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductInsertQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => queryBuilder),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            })
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.createProduct({
            name: 'Test Product',
          })
        })
      }).rejects.toThrow()
    })
  })

  describe('updateProduct', () => {
    it('should update product successfully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductUpdateQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.updateProduct('prod-123', {
          name: 'Updated Product',
          description: 'Updated description',
        })
      })

      // Assert - should not throw
      expect(true).toBe(true)
    })

    it('should update price when price changes', async () => {
      // Arrange
      const mockProducts = [
        createMockProduct({
          id: 'prod-123',
          name: 'Test Product',
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let priceInsertCalled = false

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductUpdateQueryBuilder()
        }
        if (table === 'price_ledger') {
          return createPriceInsertQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createPriceInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => {
            priceInsertCalled = true
            return Promise.resolve({
              data: null,
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      // Manually set products state
      await act(async () => {
        // We need to fetch products first to have them in state
        result.current.products.push({
          ...mockProducts[0],
          current_price: { product_id: 'prod-123', price: 45.5, currency: 'TRY', created_at: new Date().toISOString() },
        } as any)
      })

      await act(async () => {
        await result.current.updateProduct('prod-123', {
          name: 'Updated Product',
          price: 55.0, // Different price
        })
      })

      // Assert
      expect(priceInsertCalled).toBe(true)
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useProducts(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.updateProduct('prod-123', {
            name: 'Updated Product',
          })
        })
      }).rejects.toThrow('Organization ID is required')
    })
  })

  describe('deleteProduct', () => {
    it('should delete product successfully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductDeleteQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductDeleteQueryBuilder() {
        const queryBuilder = {
          delete: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.deleteProduct('prod-123')
      })

      // Assert - should not throw
      expect(true).toBe(true)
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useProducts(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.deleteProduct('prod-123')
        })
      }).rejects.toThrow('Organization ID is required')
    })

    it('should handle database error during deletion', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductDeleteQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductDeleteQueryBuilder() {
        const queryBuilder = {
          delete: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.deleteProduct('prod-123')
        })
      }).rejects.toThrow()
    })
  })

  describe('toggleVisibility', () => {
    it('should toggle product visibility successfully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedVisibility: boolean | undefined

      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createProductUpdateQueryBuilder()
        }
        return createEmptyQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createProductUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn((data: any) => {
            capturedVisibility = data.is_visible
            return queryBuilder
          }),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      function createEmptyQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useProducts(mockOrganizationId))

      await act(async () => {
        await result.current.toggleVisibility('prod-123', false)
      })

      // Assert
      expect(capturedVisibility).toBe(false)
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useProducts(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.toggleVisibility('prod-123', true)
        })
      }).rejects.toThrow('Organization ID is required')
    })
  })
})
